package main

import "fmt"

// makeCounter returns a closure over its own local `count`.
// `count` escapes to the heap because the returned func outlives this frame.
func makeCounter() func() int {
	count := 0
	return func() int {
		count++ // captured by reference: mutates the same `count`
		return count
	}
}

func main() {
	a := makeCounter() // fresh `count` cell #1
	b := makeCounter() // fresh `count` cell #2 (independent)

	fmt.Println(a()) // 1
	fmt.Println(a()) // 2
	fmt.Println(a()) // 3

	fmt.Println(b()) // 1 — b does NOT share a's state
	fmt.Println(a()) // 4 — a kept counting independently
}

package main

import (
	"fmt"
	"sync"
)

func main() {
	var wg sync.WaitGroup
	items := []string{"a", "b", "c"}

	// PRE-Go 1.22 BUG: one shared `it` reused every iteration.
	// All goroutines read `it` when they run (after the loop), so on
	// Go < 1.22 this could print "c c c". Go 1.22+ makes `it`
	// per-iteration, so it correctly prints a, b, c (in some order).
	for _, it := range items {
		wg.Add(1)
		go func() {
			defer wg.Done()
			fmt.Println("buggy-on-old-go:", it)
		}()
	}
	wg.Wait()

	// FIX 1 (works on every Go version): shadow with a per-iteration copy.
	for _, it := range items {
		wg.Add(1)
		it := it // new variable each iteration; closure captures the copy
		go func() {
			defer wg.Done()
			fmt.Println("shadow-fix:", it)
		}()
	}
	wg.Wait()

	// FIX 2 (works on every Go version): pass the value as an argument.
	for _, it := range items {
		wg.Add(1)
		go func(v string) {
			defer wg.Done()
			fmt.Println("arg-fix:", v) // v is a copy, captured nothing
		}(it)
	}
	wg.Wait()
}

package main

import (
	"fmt"
	"time"
)

type Server struct {
	addr    string
	timeout time.Duration
	tls     bool
}

// Option is a closure that configures a *Server.
type Option func(*Server)

func WithTimeout(d time.Duration) Option {
	return func(s *Server) { s.timeout = d } // captures d by value of the param
}

func WithTLS() Option {
	return func(s *Server) { s.tls = true }
}

func NewServer(addr string, opts ...Option) *Server {
	s := &Server{addr: addr, timeout: 30 * time.Second} // defaults
	for _, opt := range opts {
		opt(s) // apply each closure
	}
	return s
}

func main() {
	s := NewServer(":8080", WithTimeout(5*time.Second), WithTLS())
	fmt.Printf("%s timeout=%s tls=%t\n", s.addr, s.timeout, s.tls)
}
